import Foundation
import Testing
@testable import KunjWorkspaceCore

@Suite struct OverviewTests {
    /// `kunj agent overview --containers --json` as kunj prints it (generated by
    /// scripts/gen-overview-demo.js from kunj's own layout)
    func fixture() async throws -> AgentOverviewJson {
        try await fakeKunjCLI().run(agentOverviewArguments(), cwd: "/")
    }

    @Test func arguments() {
        #expect(agentOverviewArguments() == ["agent", "overview", "--containers"])
    }

    @Test func decodesWhatKunjLaidOut() async throws {
        let o = try await fixture()
        #expect(o.repo.name == "kunj")
        #expect(o.agents == 4)
        #expect(o.waiting == 1)
        #expect(o.summary == "4 agents · 1 waiting for you")
        #expect(o.metrics.labelWidth == 248)
        #expect(o.metrics.stopSpacing == 116)
        #expect(o.containers?.available == true)
        // the ended agent is not among them; the handed-off one is under its parent
        #expect(o.families.map { $0.lanes.count } == [2, 1, 1])

        let root = o.families[0].lanes[0]
        #expect(root.title == "Agent overview window")
        #expect(root.place == "feat/agent-overview · worktree")
        #expect(root.status == "Step 4 of 6")
        #expect(root.id == nil)
        #expect(!root.child)
        #expect(root.elbow == nil)
        #expect(root.stops.map { $0.x } == [56, 172, 288, 404, 520, 636])
        #expect(root.stops.map { $0.stopKind } == [.done, .done, .done, .current, .todo, .todo])
        #expect(root.line == OverviewLine(fromX: 56, toX: 636, doneToX: 404))
        #expect(root.loops.count == 1)
        #expect(root.loops[0].running)
        #expect(root.loops[0].label == "subagent · write reducer tests")
        #expect(root.loops[0].stops.count == 3)

        let child = o.families[0].lanes[1]
        #expect(child.child)
        #expect(child.place == "handoff · feat/agent-overview-app")
        #expect(child.elbow?.fromX == 172)
        #expect(child.top == root.height)

        let waiting = o.families[1].lanes[0]
        #expect(waiting.waiting)
        #expect(waiting.status == "Waiting for input")
        #expect(waiting.markers.map { $0.label } == ["main → feat/vscode-search"])

        let noList = o.families[2].lanes[0]
        #expect(noList.container == "kunj-kunj-fix-remote-pty")
        #expect(noList.labelBeside)
        #expect(noList.line == nil)
        #expect(noList.stops.map { $0.label } == ["No task list yet"])
    }

    @Test func aStopKindThisBuildDoesNotKnowIsDrawnAsToCome() {
        #expect(OverviewStop(x: 0, y: 0, kind: "paused", label: "x").stopKind == .todo)
        #expect(OverviewStop(x: 0, y: 0, kind: "done", label: "x").stopKind == .done)
    }

    @Test func aFamilyIsShownWhenAnyLanePassesTheFilter() async throws {
        let families = try await fixture().families
        #expect(filterFamilies(families, .all).count == 3)
        #expect(filterFamilies(families, .waiting).map { $0.lanes[0].title } == ["Search in VS Code"])
        #expect(filterFamilies(families, .running).map { $0.lanes[0].title } == ["Agent overview window", "Remote terminal hangup"])
        // a family with one waiting lane is in both
        var mixed = families[0]
        mixed.lanes[1].waiting = true
        #expect(filterFamilies([mixed], .waiting).count == 1)
        #expect(filterFamilies([mixed], .running).count == 1)
    }

    @Test func theSummaryIsKunjsForOneRepositoryAndTheTotalsForMore() async throws {
        let one = try await fixture()
        #expect(overviewSummary([one]) == "4 agents · 1 waiting for you")
        var other = one
        other.agents = 1
        other.waiting = 0
        #expect(overviewSummary([one, other]) == "5 agents · 1 waiting for you")
        var quiet = one
        quiet.agents = 1
        quiet.waiting = 0
        #expect(overviewSummary([quiet, quiet]) == "2 agents")
        var none = one
        none.agents = 0
        none.waiting = 0
        #expect(overviewSummary([none, none]) == "No agents running")
        #expect(overviewSummary([]) == "No agents running")
    }

    @Test func aClickFindsItsLane() async throws {
        let family = try await fixture().families[0]
        #expect(laneIndex(at: 5, in: family) == 0)
        #expect(laneIndex(at: family.lanes[1].top + 1, in: family) == 1)
        #expect(laneIndex(at: family.height + 1, in: family) == nil)
        #expect(laneIndex(at: -1, in: family) == nil)
    }
}

@Suite struct OverviewScopeTests {
    let a = RepoRef(name: "a", root: "/a", bare: false, dirName: "a")
    let b = RepoRef(name: "b", root: "/b", bare: false, dirName: "b")
    let c = RepoRef(name: "c", root: "/c", bare: false, dirName: "c")

    @Test func scopePicksTheRepositories() {
        let repos = [a, b, c]
        #expect(overviewRepos(repos, open: ["/c", "/a"], scope: .open) == [a, c])
        #expect(overviewRepos(repos, open: [], scope: .open).isEmpty)
        #expect(overviewRepos(repos, open: ["/a"], scope: .all) == repos)
        #expect(overviewRepos(repos, open: [], scope: .repo("/b")) == [b])
        #expect(overviewRepos(repos, open: [], scope: .repo("/gone")).isEmpty)
    }

    @Test func scopeTitles() {
        #expect(overviewScopeTitle(.open, repos: [a, b], open: ["/a"]) == "Open sessions (1 repository)")
        #expect(overviewScopeTitle(.open, repos: [a, b], open: ["/a", "/b"]) == "Open sessions (2 repositories)")
        #expect(overviewScopeTitle(.all, repos: [a], open: []) == "All repositories")
        #expect(overviewScopeTitle(.repo("/b"), repos: [a, b], open: []) == "b")
    }
}
